import{_ as o,o as t,c as a,a2 as l}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"ja/self-hosted/desktop.md","filePath":"ja/self-hosted/desktop.md","lastUpdated":1792323081000}'),r={name:"ja/self-hosted/desktop.md"};function s(i,e,p,d,h,n){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h1><p>Memoh Desktop は、Memoh Cloud またはセルフホストの Memoh サーバーに接続するネイティブクライアントです。同じクライアント画面を Electron シェルに包み、ネイティブウィンドウ・トレイ・メニュー・ショートカットを提供し、動かしているこのコンピューターを Bot が使える <strong>コンピューター</strong> として登録することもできます。</p><p>Desktop は<strong>自分ではローカルサーバーやデータベースを動かしません</strong>。常にいずれかの Memoh サーバーに接続します：<a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a> か、自分の <a href="./docker.html">Server Deploy</a> です。</p><h2 id="desktop-を使う場面" tabindex="-1">Desktop を使う場面 <a class="header-anchor" href="#desktop-を使う場面" aria-label="Permalink to &quot;Desktop を使う場面&quot;">​</a></h2><p>次のような場面に向いています：</p><ul><li>ブラウザのタブではなく、ネイティブなアプリウィンドウとシステムトレイがほしい</li><li>日々の Memoh ワークフローをネイティブメニューとショートカットでこなしたい</li><li>サーバー側の Bot にこの PC のファイル・シェル・ブラウザを使わせたいが、別の runtime プロセスは動かしたくない</li></ul><p>たまにブラウザから覗くだけなら、ウェブクライアントで十分です。</p><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><ol><li><a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">Memoh Desktop ダウンロードページ</a>から、お使いのプラットフォーム向けインストーラー（macOS DMG、Windows NSIS、Linux AppImage/deb/rpm）をダウンロードします。</li><li>Memoh を開きます。</li><li>接続画面でサーバーアドレスを入力します（または Memoh Cloud を選択）。</li><li>Memoh アカウントでサインインします。</li></ol><h2 id="サーバーへの接続" tabindex="-1">サーバーへの接続 <a class="header-anchor" href="#サーバーへの接続" aria-label="Permalink to &quot;サーバーへの接続&quot;">​</a></h2><p>接続画面でサーバーアドレスを入力して接続します：</p><ul><li>素のドメイン（例 <code>memoh.example.com</code>）は <code>https://</code> として扱われます（localhost 系アドレスのみ既定で <code>http://</code>）。</li><li><code>/api</code> サフィックスがなければ自動で補われるので、ドメインだけで十分です。</li><li>Desktop は先にサーバーの <code>/ping</code> を確認し（タイムアウト 5 秒）、成功するとサインイン画面へ進みます。</li></ul><p>別のサーバーに切り替えるとローカルのサインイン状態はクリアされ、再ログインが必要になります。</p><h2 id="この-pc-を-bot-に共有する" tabindex="-1">この PC を Bot に共有する <a class="header-anchor" href="#この-pc-を-bot-に共有する" aria-label="Permalink to &quot;この PC を Bot に共有する&quot;">​</a></h2><p>Desktop は、動かしているマシンをサーバー側 Bot が使える <strong>コンピューター</strong> として登録できます。別の runtime プロセスは不要です：<strong>このコンピューター</strong> のスイッチを入れて名前を付ければ、Desktop が内蔵の Memoh runtime SDK でバックグラウンドの接続を維持します。資格情報は OS のセキュアストレージに保存されます。</p><p>権限は Bot ごとに付与し、書き込みと実行は既定で承認が必要です——詳しくは<a href="./../guides/access.html">アクセス制御</a>を参照してください。</p><h2 id="desktop-が担うもの" tabindex="-1">Desktop が担うもの <a class="header-anchor" href="#desktop-が担うもの" aria-label="Permalink to &quot;Desktop が担うもの&quot;">​</a></h2><ul><li>アプリウィンドウ、トレイアイコン、再表示と終了の挙動</li><li>ウェブクライアントとコマンドレジストリを共有するネイティブメニュー</li><li>選択したサーバーへの接続と、キャッシュされたサインイン状態</li><li><strong>このコンピューター</strong> に対応する任意の Remote Runtime 接続</li></ul><p>それ以外のすべて（Bot、セッション、メモリ、ワークスペース、チャネル）は接続先のサーバー上にあります。ワークスペースのランタイムはサーバー側で設定します。詳しくは <a href="./workspace-backends.html">Workspace バックエンド</a>を参照してください。</p>',19)])])}const k=o(r,[["render",s]]);export{m as __pageData,k as default};
